window.VOLCANO_MODEL={"name":"volcano.glb","verts":10893,"tris":8762,"bbox":{"min":[-0.406,0.0488,-0.3621],"max":[0.3928,0.7886,0.3674]},"material":{"baseColorFactor":[0.800000011920929,0.800000011920929,0.800000011920929,1],"metallic":1,"roughness":1},"encoding":{"position":"Float32","normal":"Float32","uv":"Float32","index":"Uint16Array"},"position":"","normal":"","uv":"","index":""};
window.__glbDecode=function(m,THREE){const d=(s,T)=>{const b=atob(s),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return new T(a.buffer)};
 const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(d(m.position,Float32Array),3));
 if(m.normal)g.setAttribute('normal',new THREE.BufferAttribute(d(m.normal,Float32Array),3));else g.computeVertexNormals();
 if(m.uv)g.setAttribute('uv',new THREE.BufferAttribute(d(m.uv,Float32Array),2));
 if(m.index)g.setIndex(new THREE.BufferAttribute(d(m.index,Uint16Array),1));
 g.computeBoundingBox();return g};

